INSERT INTO historical_events (title, year, latitude, longitude, description, ripple_effect, track, category, special_action) VALUES
('史前文明起源與採集', -3900, 9, 38.7, '早期人類依賴舊石器打製石器，已知用火、馴化家犬，並逐步發展出農耕。', ARRAY['開啟了對自然資源的最初步馴化。'], 'WORLD', '政治軍事', NULL),
('烏魯克城市文明與楔形文字', -3500, 31.3, 45.6, '兩河流域進入烏魯克時期，創造世界上最早的文字——楔形文字。', ARRAY['文字發明使人類能跨越時空積累知識。'], 'WORLD', '政治軍事', NULL),
('漢穆拉比法典頒布', -1792, 32.5, 44.4, '古巴比倫國王漢穆拉比制定《漢穆拉比法典》。', ARRAY['實行『以眼還眼』的同態復仇原則。'], 'WORLD', '政治軍事', NULL),
('蘇格拉底在世', -469, 37.9, 23.7, '首創『蘇格拉底提問法』，將哲學探究核心轉向人類道德與心靈。', ARRAY['奠定西方理性批判基礎。'], 'WORLD', '政治軍事', NULL),
('屋大維與羅馬帝國', -27, 41.9, 12.5, '屋大維被尊為奧古斯都，羅馬進入帝國時期。', ARRAY['羅馬法深遠影響近代西方。'], 'WORLD', '政治軍事', NULL),
('夏朝建立', -2070, 34.7, 112.8, '傳說中中國第一個世襲王朝，以黃河流域為核心地區。', ARRAY['開啟了『家天下』的世襲政治制度。'], 'CN', '政治軍事', NULL),
('商朝建立', -1600, 36.1, 114.3, '中國第一個有直接文字記載（甲骨文）的王朝，青銅文明發達。', ARRAY['甲骨文奠定漢字基礎，宗教祭祀影響深遠。'], 'CN', '政治軍事', NULL),
('武王伐紂建周 (西周)', -1046, 34.2, 108.9, '武王伐紂滅商，建立周朝，實施宗法與封建制度。', ARRAY['奠定中國早期封建政治與禮樂文化基礎。'], 'CN', '政治軍事', NULL),
('平王東遷與春秋時期', -770, 34.7, 112.4, '周平王東遷洛邑，王權衰落，進入春秋五霸諸侯爭霸時期。', ARRAY['封建制度逐漸鬆動。'], 'CN', '政治軍事', NULL),
('戰國時期', -475, 34.7, 112.4, '三家分晉，進入戰國七雄兼併戰爭的時期，各國紛紛變法圖強。', ARRAY['促成了中央集權國家的雛形與百家爭鳴。'], 'CN', '政治軍事', NULL),
('秦滅六國大一統', -221, 34.3, 108.9, '始皇帝開創皇帝制度、推行郡縣制、統一文字與度量衡。', ARRAY['確立東亞大陸的中央集權政治架構。'], 'CN', '政治軍事', NULL),
('劉邦建立西漢', -202, 34.3, 108.9, '劉邦擊敗項羽，建立漢朝，初期實施休養生息與郡國並行制。', ARRAY['延續了秦朝的大一統格局並加以鞏固。'], 'CN', '政治軍事', NULL),
('漢武帝盛世與擴張', -134, 34.3, 108.9, '漢武帝罷黜百家獨尊儒術，並對外大舉擴張，將西域、南越、朝鮮半島北部納入版圖。', ARRAY['奠定了漢人、漢字、漢文化的深厚基礎，開通絲綢之路。'], 'CN', '政治軍事', NULL),
('孔子與儒家思想誕生', -551, 35.6, 116.9, '孔子創立儒家學派，首創私人講學。', ARRAY['成為兩千年東亞社會控制核心。'], 'CN', '政治軍事', NULL),
('光武中興與東漢建立', 25, 34.7, 112.4, '劉秀重建漢朝，定都洛陽，史稱東漢。', ARRAY['豪族勢力逐漸擴大，影響後世社會結構。'], 'CN', '政治軍事', NULL),
('三國鼎立', 220, 34.3, 108.9, '曹丕篡漢，隨後劉備、孫權相繼稱帝，天下三分。', ARRAY['促進了江南與西南地區的開發。'], 'CN', '政治軍事', NULL),
('西晉短暫統一', 280, 34.7, 112.4, '晉滅吳，結束三國分裂，但不久即爆發八王之亂。', ARRAY['九品中正制導致世族壟斷政治。'], 'CN', '政治軍事', NULL),
('永嘉之禍與衣冠南渡', 311, 34.7, 112.4, '匈奴攻陷洛陽，晉室南遷建立東晉，北方進入五胡十六國。', ARRAY['促成中國歷史上第一次大規模人口南遷，加速江南開發。'], 'CN', '政治軍事', NULL),
('劉裕建宋 (南朝開始)', 420, 32, 118.8, '劉裕篡晉建宋，南朝開始，江南經濟持續發展。', ARRAY['確立了南朝政權的更迭模式，江南農業與文化繁榮。'], 'CN', '政治軍事', NULL),
('北魏統一北方', 439, 40.1, 113.3, '鮮卑族建立的北魏統一了黃河流域，結束五胡十六國的分裂局面。', ARRAY['北方逐漸走向民族融合。'], 'CN', '政治軍事', NULL),
('北魏孝文帝遷都與漢化', 493, 34.7, 112.4, '孝文帝將首都從平城遷至洛陽，並全面推行漢化政策（改漢姓、穿漢服、通漢婚）。', ARRAY['極大地促進了胡漢民族的深度融合，為後來隋唐大一統奠定基礎。'], 'CN', '政治軍事', NULL),
('隋朝統一與大運河', 589, 34.3, 108.9, '隋滅陳，結束南北朝近三百年的分裂；開鑿大運河溝通南北。', ARRAY['確立三省六部與科舉制，奠定唐朝盛世基礎。'], 'CN', '政治軍事', NULL),
('耶穌遇難與基督教傳布', 30, 31.7, 35.2, '耶穌被釘十字架，門徒傳布基督教。', ARRAY['發展為影響全球的世界性宗教。'], 'WORLD', '政治軍事', NULL),
('羅馬帝國正式分裂', 395, 41.9, 12.5, '帝國正式分裂為東、西羅馬帝國。', ARRAY['東羅馬延續千年，西羅馬逐漸瓦解。'], 'WORLD', '政治軍事', NULL),
('穆罕默德聖遷', 622, 24.4, 39.6, '逃亡至麥地那，定為伊斯蘭教回曆元年。', ARRAY['阿拉伯帝國迅速擴張。'], 'WORLD', '政治軍事', NULL),
('第一次十字軍東征', 1096, 31.7, 35.2, '教宗號召十字軍東征。', ARRAY['促進東西方貿易與文化交流。'], 'WORLD', '政治軍事', NULL),
('成吉思汗建立大蒙古國', 1206, 47.9, 106.9, '鐵木真統一蒙古，建立大蒙古國。', ARRAY['建立橫跨歐亞的超級帝國。'], 'WORLD', '政治軍事', NULL),
('馬丁路德與宗教改革', 1517, 51.8, 12.6, '張貼九十五條論綱。', ARRAY['打破羅馬公教單一權威。'], 'WORLD', '政治軍事', NULL),
('麥哲倫環球航行出發', 1519, 36.7, -6.3, '麥哲倫率西班牙船隊尋找香料群島。', ARRAY['證明地圓說，開啟全球海洋貿易時代。'], 'WORLD', '政治軍事', NULL),
('法國大革命爆發', 1789, 48.8, 2.3, '巴黎人民攻陷巴士底監獄，推翻專制。', ARRAY['自由、平等的思想震撼全歐洲。'], 'WORLD', '政治軍事', NULL),
('拿破崙稱帝', 1804, 48.8, 2.3, '拿破崙加冕為法蘭西第一帝國皇帝。', ARRAY['將大革命精神與民法典強制推廣至歐洲各地。'], 'WORLD', '政治軍事', NULL),
('唐朝建立', 618, 34.3, 108.9, '李淵稱帝建立唐朝。', ARRAY['發展出極盛的東亞文化圈。'], 'CN', '政治軍事', NULL),
('平定東突厥與天可汗體系', 630, 41, 111, '唐太宗擊敗東突厥，被西北各族尊為「天可汗」，疆域廣闊。', ARRAY['確立了唐帝國在東亞及中亞的霸主地位，絲路貿易大盛。'], 'CN', '政治軍事', NULL),
('安史之亂', 755, 34.3, 108.9, '安祿山、史思明起兵叛唐，唐朝由盛轉衰。', ARRAY['導致藩鎮割據，經濟重心進一步南移。'], 'CN', '政治軍事', NULL),
('契丹建國 (遼)', 916, 43.8, 119.2, '耶律阿保機建立契丹國（後改稱遼），並逐步南下擴張。', ARRAY['改變了東亞大陸北方的政治板塊。'], 'CN', '政治軍事', NULL),
('陳橋兵變與北宋建立', 960, 34.8, 114.3, '趙匡胤黃袍加身，建立宋朝，實行強幹弱枝、重文輕武政策。', ARRAY['造就了經濟繁榮與文化藝術的高峰，但軍事較為積弱。'], 'CN', '政治軍事', NULL),
('澶淵之盟', 1004, 35.7, 115, '北宋與遼國簽訂和平條約，以兄弟相稱並餽贈歲幣。', ARRAY['維持了宋遼之間長達百餘年的相對和平與貿易往來。'], 'CN', '政治軍事', NULL),
('靖康之禍與南宋偏安', 1127, 30.2, 120.1, '金兵攻陷汴京，俘虜徽欽二帝，宋室南渡定都臨安(杭州)。', ARRAY['中國經濟重心徹底南移完成。'], 'CN', '政治軍事', NULL),
('蒙宋聯軍滅金', 1234, 33, 114, '蒙古與南宋聯手攻陷蔡州，金朝滅亡，蒙古隨即南下侵宋。', ARRAY['蒙古徹底控制華北，南宋面臨更強大的生存威脅。'], 'CN', '政治軍事', NULL),
('忽必烈建立元朝', 1271, 39.9, 116.4, '忽必烈取《易經》「大哉乾元」之意，改國號為大元，定都大都。', ARRAY['中國歷史上第一個由北方遊牧民族建立的大一統王朝。'], 'CN', '政治軍事', NULL),
('崖山海戰與南宋滅亡', 1279, 22.2, 113.1, '元軍在崖山海戰徹底擊敗南宋殘餘水師，陸秀夫背負幼帝投海，南宋滅亡。', ARRAY['元朝完成全國大一統，結束了自唐末五代以來數百年的分裂局面。'], 'CN', '政治軍事', NULL),
('朱元璋建立大明', 1368, 32, 118.8, '朱元璋在應天府(南京)稱帝，建立明朝，隨後北伐攻陷大都，結束元朝在全國的統治。', ARRAY['恢復漢人政權，加強君主專制，廢除丞相制度。'], 'CN', '政治軍事', NULL),
('永樂盛世與鄭和下西洋', 1405, 39.9, 116.4, '明成祖朱棣派鄭和七下西洋，並將東北(奴兒干都司)、安南(交阯)短期納入版圖，威服四方。', ARRAY['確立明朝在東亞的朝貢體系霸主地位，促進海上貿易與文化交流。'], 'CN', '政治軍事', NULL),
('嘉靖大倭寇', 1550, 29.8, 121.5, '東南沿海因海禁政策引發嚴重走私與武裝衝突，史稱「嘉靖大倭患」，後由戚繼光等人平定。', ARRAY['促使明朝有限度開放海禁(隆慶開關)，白銀大量流入中國。'], 'CN', '政治軍事', NULL),
